    "b": "<p>一杯水裡有幾個水分子？精確答案需要莫耳質量和亞佛加厥數：250 mL 水是 250 g，$250/18.015 \\approx 13.9$ 莫耳，乘上 $6.022\\times10^{23}$ 得到約 $8.4\\times10^{24}$ 個。</p>\n<p>如果手邊什麼資料都沒有呢？可以這樣估：水分子大約 0.3 nm 大，一個分子占的體積約 $(3\\times10^{-10}\\ \\text{m})^3 = 2.7\\times10^{-29}\\ \\text{m}^3$；一杯水 $2.5\\times10^{-4}\\ \\text{m}^3$，相除得 $9\\times10^{24}$ 個。粗估和精算只差約 10%，數量級完全一樣。</p>\n<p>直覺卡在兩個地方：一是數字太大、太小，不知道怎麼寫和怎麼算；二是覺得「沒有精確資料就無從下手」。這一集要給你四樣工具：統一的單位、單位換算、科學記號與有效數字、數量級估算。之後每一集的計算都會用到它們。</p>"
