   {
    "h": "有效數字：計算不會讓量測變準",
    "b": "<p>有效數字告訴讀者「這個數字有多可靠」。12.3 cm 表示最後一位的 3 是估出來的；寫成 12.30 cm 則表示你量到了 0.01 cm。規則：</p>\n<table><tr><th>情況</th><th>規則</th><th>例子</th></tr>\n<tr><td>乘、除</td><td>答案的有效位數跟著位數最少的那個量</td><td>$2.0\\ \\text{m}\\times3.14159 = 6.3\\ \\text{m}$</td></tr>\n<tr><td>加、減</td><td>答案的小數位數跟著小數位最少的那個量</td><td>$12.3 + 0.456 = 12.8$</td></tr>\n<tr><td>開頭的 0</td><td>不算有效數字，只是定位</td><td>0.00450 有 3 位</td></tr></table>\n<p><b>小例題（相減會損失精度）</b>：一根金屬棒加熱前 5.269 m、加熱後 5.276 m，伸長量 $5.276 - 5.269 = 0.007\\ \\text{m}$。兩個量都有 4 位有效數字，差值卻只剩 1 位。要量小小的變化，最好直接量變化量本身。</p>\n<p>中間步驟要多留一兩位，最後答案再四捨五入，避免一路捨入累積誤差。</p>"
   },
   {
    "h": "數量級估算與資料擬合",
    "b": "<p><b>費米估算</b>：把問題拆成幾個能大概猜到的數字。例：地球大氣總共多重？</p>\n<ol><li>海平面氣壓約 $1.01\\times10^{5}\\ \\text{N/m}^2$，表示每平方公尺上方壓著約 $1.01\\times10^{5}/9.8 \\approx 1.0\\times10^{4}$ kg 的空氣（約 10 公噸）。</li>\n<li>地球表面積 $4\\pi R^2 = 4\\pi(6.37\\times10^{6}\\ \\text{m})^2 \\approx 5.1\\times10^{14}\\ \\text{m}^2$。</li>\n<li>相乘得約 $5.3\\times10^{18}$ kg。</li></ol>\n<p>估算也是檢查工具：電腦算出教室裡的空氣有 3 公斤（實際約 $10\\times8\\times3\\ \\text{m}^3\\times1.2\\ \\text{kg/m}^3 \\approx 290$ kg），你應該立刻懷疑。</p>\n<p><b>資料擬合</b>：理論常預測兩個量成正比或成平方關係。把資料改畫成會成直線的形式，斜率就是要找的量。落體距離 $y = \\tfrac12gt^2$，所以畫 $y$ 對 $t^2$ 應該是直線，斜率等於 $g/2$。</p>\n<figure class=\"fig\"><img src=\"figs/fig_01_02_drop_fit.svg\" alt=\"落下距離對時間平方的資料點與最佳擬合直線\" loading=\"lazy\"><figcaption>假設的六筆落體資料（各帶約 2% 隨機誤差）畫成 y 對 t² 幾乎成直線；擬合斜率 4.80 m/s²，得 g ≈ 9.60 m/s²，比 9.80 小約 2%。</figcaption></figure>\n<p>資料點不會剛好落在線上，擬合直線要抓整體趨勢，不必穿過任何一點。解題時也可以照四個步驟走：先看懂題目與適用的原理、畫圖並規劃要用哪些式子、代數解完再代入數字、最後檢查單位與數量級是否合理。</p>"
   },
   {
    "h": "生活與科技連結",
    "b": "<ul>\n<li><b>GPS 定位</b>：衛星上帶著原子鐘，手機靠訊號傳來的時間差算距離。光 1 ns 走約 30 cm，所以時間只要差 1 微秒，位置就差約 300 m。秒的精確定義直接決定了導航準不準。</li>\n<li><b>公斤的新定義</b>：2019 年以前，全世界的公斤都要追溯到一個鉑銥合金圓柱；現在改由普朗克常數定義，用基布爾秤（Kibble balance）這類儀器，各國實驗室都能自己重現公斤。</li>\n<li><b>醫療劑量</b>：藥品標示常同時出現 mg 和 μg，兩者差 1000 倍。看錯一個字首就是劑量差三個數量級，這也是醫護訓練特別強調單位的原因。</li>\n</ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul>\n<li><b>換算因子放反</b>：把 km/h 換成 m/s 時乘上 3600/1000，得到 324 m/s 這種離譜數字。每一步都把單位寫出來，看它們有沒有約掉。</li>\n<li><b>照抄計算機的位數</b>：12.3 ÷ 3 寫成 4.1000000，等於宣稱自己量到了千萬分之一。答案的位數要跟著原始資料的精度走。</li>\n<li><b>以為估算就是亂猜</b>：費米估算的每一步都有根據，只是只取一位數。拆成多個因子後，有的高估、有的低估，誤差會部分抵消，所以數量級通常是對的。</li>\n</ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul>\n<li>1.1 節：物理的幾大領域（力學、振動與波、熱力學、電磁學、光學、近代物理），也就是這套課程上下冊的分段。</li>\n<li>1.2 節：SI 基本單位與 2019 年以自然常數為基礎的新定義；練習用換算因子在不同單位系統間轉換。</li>\n<li>1.3 節：科學記號、有效數字的加減與乘除規則、把資料畫成直線求斜率，以及數量級估算。</li>\n<li>1.4 節：學物理的方法與四步驟解題策略（理解、規劃、計算、檢查），之後每一集的例題都照這個流程。</li>\n</ul>"
   }
