  "notes": [
   {
    "h": "一句話記住",
    "b": "功是力沿著位移方向推動物體時轉移的能量；所有力做的淨功等於動能的變化，而功率說的是能量轉換得有多快。"
   },
   {
    "h": "為什麼需要它",
    "b": "<p>提著 8 kg 的書包站一小時，手痠得要命，但書包的位置、速度都沒變，你沒有把任何能量交給它，物理上做功是零。改成提著它走上三層樓、升高 9.0 m，你對書包做的功是 $8\\times9.80\\times9.0 \\approx 706\\ \\text{J}$，不到一小時站立消耗的零頭。</p>\n<p>這說明「累」和「功」是兩回事。物理上的功要追蹤的是<b>能量從誰轉移到誰</b>。</p>\n<p>為什麼要引入這個新角度？上冊 EP4、EP5 用 $\\vec{F} = m\\vec{a}$ 一刻一刻追蹤加速度，力一旦隨位置改變（彈簧、重力隨高度變化），計算就變得很麻煩。改問「力推過一段距離總共轉移多少能量」，常常一步就能得到末速率，完全不必知道中間每一刻的加速度。</p>"
   },
   {
    "h": "功與純量積",
    "b": "<p>定力 $\\vec{F}$ 讓物體位移 $\\Delta\\vec{r}$，功是</p>\n$$W = \\vec{F}\\cdot\\Delta\\vec{r} = F\\,\\Delta r\\cos\\theta.$$\n<p>讀法：只有沿著位移方向的那一段力分量 $F\\cos\\theta$ 有貢獻。θ < 90° 時功為正（力幫忙推，物體得到能量）；θ = 90° 時功為零（例如正向力、等速圓周運動的向心力）；θ > 90° 時功為負（例如摩擦力、煞車）。</p>\n<p>用分量計算時，點積就是對應分量相乘再相加：$\\vec{A}\\cdot\\vec{B} = A_xB_x + A_yB_y + A_zB_z$。</p>\n<p><b>小例題</b>：力 $\\vec{F} = (3.0\\,\\hat{\\imath} + 4.0\\,\\hat{\\jmath})\\ \\text{N}$，位移 $\\Delta\\vec{r} = (5.0\\,\\hat{\\imath} - 2.0\\,\\hat{\\jmath})\\ \\text{m}$，功 $W = 3.0\\times5.0 + 4.0\\times(-2.0) = 7.0\\ \\text{J}$。y 方向的力和 y 方向的位移相反，貢獻 −8 J。</p>\n<p><b>小例題</b>：以 150 N、仰角 30° 拉行李箱水平走 40 m，$W = 150\\times40\\times\\cos30^\\circ \\approx 5.2\\ \\text{kJ}$；拉力的鉛直分量 75 N 沒有做功，只是減輕了地板的正向力。</p>"
   },
   {
    "h": "變力的功：把面積累加起來",
    "b": "<p>力隨位置改變時，把路徑切成很多小段 $dx$，每一小段裡力幾乎不變，功是 $F\\,dx$，再全部累加（積分）：</p>\n$$W = \\int_{x_1}^{x_2} F(x)\\,dx.$$\n<p>幾何意義很直觀：<b>功就是 F–x 圖曲線底下的面積</b>。定力時面積是長方形 $F\\Delta x$，就回到前面的公式。</p>\n<p>理想彈簧遵守虎克定律，拉長 $x$ 需要的拉力是 $F = kx$（彈簧自己的恢復力是 $-kx$）。從 $x_1$ 拉到 $x_2$ 所做的功是梯形面積：</p>\n$$W = \\int_{x_1}^{x_2} kx\\,dx = \\tfrac12 k x_2^2 - \\tfrac12 k x_1^2.$$\n<p><b>小例題</b>：假設 $k = 200\\ \\text{N/m}$，從伸長 10 cm 拉到 20 cm，$W = \\tfrac12\\times200\\times(0.20^2 - 0.10^2) = 3.0\\ \\text{J}$。從 0 拉到 10 cm 只要 1.0 J，第二個 10 cm 卻要 3 倍，因為後半段的力比較大。</p>\n<figure class=\"fig\"><img src=\"figs/fig_06_01_spring_work_area.svg\" alt=\"彈簧力與伸長量的直線圖，10 到 20 公分之間塗色的面積\" loading=\"lazy\"><figcaption>綠色面積就是功。切成 5 個小梯形累加得到 3.0 J，和公式 ½k(x₂² − x₁²) 一致；直線力的梯形累加剛好沒有誤差。</figcaption></figure>"
   },
   {
    "h": "動能與功能定理",
    "b": "<p>對物體做淨功，它的速率會改變。在一維、定力的情況，$F = ma$ 配上 $v_2^2 = v_1^2 + 2a\\Delta x$，兩邊乘 $m/2$ 就得到</p>\n$$W_{\\text{net}} = F\\Delta x = \\tfrac12 mv_2^2 - \\tfrac12 mv_1^2 = \\Delta K.$$\n<p>這個結果對變力、曲線路徑也成立，叫作<b>功能定理</b>：所有力做的功加起來，等於動能的變化。動能 $K = \\tfrac12 mv^2$ 是純量，永遠不為負。</p>\n<p><b>小例題</b>：1000 kg 的車，20 m/s 時動能 200 kJ，40 m/s 時 800 kJ。速率加倍，動能變 4 倍。</p>\n<p><b>小例題（煞車距離）</b>：輪胎鎖死時只有動摩擦做功，$-\\mu_k mg\\,d = 0 - \\tfrac12 mv^2$，所以 $d = v^2/(2\\mu_k g)$。25 m/s、$\\mu_k = 0.70$ 時 $d \\approx 45.6\\ \\text{m}$；同樣車速在濕滑路面（假設 $\\mu_k = 0.40$）要 $79.7\\ \\text{m}$。</p>\n<figure class=\"fig\"><img src=\"figs/fig_06_02_braking_distance.svg\" alt=\"煞車距離隨車速變化的曲線，比較乾燥與濕滑路面\" loading=\"lazy\"><figcaption>煞車距離和車速平方成正比：90 km/h 時乾燥路面約 46 m、濕滑路面約 80 m，還沒算上反應時間行駛的距離。</figcaption></figure>"
   },
   {
    "h": "功率",
    "b": "$$P = \\frac{dW}{dt},\\qquad \\text{定力時}\\ P = \\vec{F}\\cdot\\vec{v}$$\n<p>讀法：功率是做功的快慢，也就是每秒轉移多少焦耳。單位瓦特 $1\\ \\text{W} = 1\\ \\text{J/s}$；馬力 $1\\ \\text{hp} \\approx 746\\ \\text{W}$。</p>\n<p><b>小例題</b>：60 kg 的學生 15 s 爬上 12 m 高的樓梯，對自己做功 $60\\times9.80\\times12 \\approx 7.06\\ \\text{kJ}$，平均功率 $7056/15 \\approx 470\\ \\text{W}$，約 0.63 hp。</p>\n<p><b>小例題</b>：800 kg 的電梯等速 2.5 m/s 上升，馬達拉力等於重力 7840 N，功率 $P = Fv = 19.6\\ \\text{kW}$。</p>\n<p>電費帳單的「度」是千瓦小時，$1\\ \\text{kWh} = 1000\\ \\text{W}\\times3600\\ \\text{s} = 3.6\\times10^{6}\\ \\text{J}$，是能量單位，不是功率單位。1200 W 的吹風機用 10 分鐘，耗電 $1.2\\times(10/60) = 0.2$ 度。</p>"
   },
   {
    "h": "生活與科技連結",
    "b": "<ul>\n<li><b>汽車安全距離</b>：煞車距離和車速平方成正比，所以高速公路的建議車距比市區長得多；雨天摩擦係數下降，距離還要再加長。</li>\n<li><b>家電功率與電費</b>：電器銘牌上的瓦數是功率，乘上使用時間才是用掉的能量（度數）。功率大的電器若只開一下，電費不一定比功率小但整天開著的電器多。</li>\n<li><b>運動手錶的功率計</b>：自行車功率計量測踩踏的力和踏板速度，相乘得到騎士的輸出功率，用來安排訓練強度。</li>\n</ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul>\n<li><b>以為出力就是做功</b>：位移為零，或力和位移垂直，功都是零。提著書包水平走路，手的拉力是鉛直的，對書包做功也是零。</li>\n<li><b>忘了功可以是負的</b>：摩擦力、煞車、往上丟球時的重力，都和位移反向，做負功，讓動能減少。功的正負代表能量流進或流出物體，不是方向。</li>\n<li><b>把功率和能量搞混</b>：瓦特是「每秒多少焦耳」，千瓦小時才是能量。說太陽能板「每小時發 3 kW」是把兩者混在一起，正確說法是「功率 3 kW」，一小時發 3 度電。</li>\n</ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul>\n<li>6.1 節：能量的概念與各種形式；先建立「能量會轉換、總量守恆」的大圖像。</li>\n<li>6.2 節：定力的功與純量積；練習判斷功的正負，以及哪些力（正向力、向心力）不做功。</li>\n<li>6.3 節：變力的功是 F–x 曲線下的面積（積分）；彈簧的功 ½kx² 是代表例子。</li>\n<li>6.4 節：動能與功能定理；用它直接從力和距離算出末速率。</li>\n<li>6.5 節：功率是能量轉換的快慢，P = F·v；分清楚瓦特與千瓦小時。</li>\n</ul>"
   }
  ],
