    "q": "國際太空站離地面只有約 400 km，大約是地球半徑的 6%。那裡的重力比地面小很多嗎？太空人為什麼會飄起來？",
    "a": "400 km 高處的重力加速度大約還有地面的 89%。太空人會飄，是因為太空站和太空人一起以同樣的加速度在「自由落下」，只是水平速度夠快，一直落不到地面而繞著地球轉，彼此之間沒有相對加速度，所以感覺失重。"
