    "q": "把砲彈從高山上水平射出，射得越快落得越遠。如果快到某個程度，會發生什麼事？",
    "a": "地表是彎的。速度夠快時，砲彈往下落的同時，地面也因為曲率「彎下去」了同樣的量，砲彈就一直落不到地面，變成繞地球轉的衛星。地表附近這個速率約每秒 7.9 公里。"
