  "formula": "\\vec{r}_{\\text{cm}} = \\frac{\\sum_i m_i\\vec{r}_i}{M},\\qquad \\vec{F}_{\\text{ext}} = M\\vec{a}_{\\text{cm}} = \\frac{d\\vec{P}}{dt}",
