    "h": "常見陷阱",
    "b": "<ul>\n<li><b>rpm 沒換成 rad/s</b>：$v = \\omega r$、$K = \\tfrac12 I\\omega^2$ 都要用弧度。1 rpm $= 2\\pi/60 \\approx 0.105\\ \\text{rad/s}$，直接代 rpm 會差將近 10 倍（動能差近 100 倍）。</li>\n<li><b>以為轉動慣量只看質量</b>：$I$ 取決於質量和轉軸的位置。同一根棒繞中點和繞一端相差四倍；查表時一定要看是哪一條軸。</li>\n<li><b>滾動時漏掉轉動動能</b>：用 $mgh = \\tfrac12 mv^2$ 算滾動的球，會高估速度。滾動要寫 $\\tfrac12 Mv^2 + \\tfrac12 I\\omega^2$，並用 $\\omega = v/R$ 連起來。</li>\n</ul>"
