   {
    "h": "為什麼需要它",
    "b": "<p>相機閃光燈按下快門前，常會聽到一陣高頻「嗶——」聲，等幾秒才能閃。閃光只持續約一毫秒，卻需要很大的瞬間功率，電池本身送不出這麼大的電流。</p>\n<p>解法是先把能量慢慢存起來，再一口氣放掉。假設閃光燈裡的電容器是 120 μF、充到 330 V，存的能量</p>\n$$U = \\tfrac{1}{2}CV^2 = \\tfrac{1}{2}(120\\times10^{-6})(330)^2 \\approx 6.5\\ \\text{J}.$$\n<p>如果在 1 ms 內放完，平均功率約 6.5 kW，遠超過電池能直接提供的。電池花幾秒、用小電流把能量搬進電容器，電容器再瞬間釋放。這一集要回答：電荷堆在一起時能量存在哪裡、電容器能存多少電荷與能量、怎麼讓它存更多。</p>"
   },
   {
    "h": "靜電能：把電荷湊在一起的功",
    "b": "<p>兩顆點電荷從無窮遠處被推到相距 $r$，外力做的功等於它們的電位能：</p>\n$$U_{12} = \\frac{kq_1q_2}{r}.$$\n<p>同號為正（要用力推近），異號為負（它們自己會靠過來）。三顆以上電荷時，把<b>每一對</b>的 $kq_iq_j/r_{ij}$ 加起來，每一對只算一次。</p>\n<p><b>小例題</b>：三顆 +2.0 nC 放在邊長 3.0 cm 的正三角形三個頂點，共有三對，</p>\n$$U = 3\\times\\frac{(8.99\\times10^9)(2.0\\times10^{-9})^2}{0.030} \\approx 3.6\\times10^{-6}\\ \\text{J}.$$\n<p>這是把它們組合起來所需的功，也是放手後三顆電荷互相推開、全部跑到很遠時的總動能。</p>"
   },
   {
    "h": "電容：每伏特能存多少電荷",
    "b": "<p>任何兩個彼此絕緣的導體都是電容器。充電時，電池把電子從一邊搬到另一邊，一個導體帶 $+Q$、另一個帶 $-Q$，兩者之間出現電位差 $V$。電場與電位差都和 $Q$ 成正比，所以比值固定：</p>\n$$C = \\frac{Q}{V}.$$\n<p><b>平行板電容器</b>：板面積 $A$、間距 $d$。用上一集的結果，板間電場 $E = \\sigma/\\varepsilon_0 = Q/\\varepsilon_0 A$，電位差 $V = Ed$，於是</p>\n$$C = \\frac{\\varepsilon_0 A}{d}.$$\n<p>讀法：板越大能放越多電荷，板越近同樣的電荷只需要越小的電位差。<b>小例題</b>：10 cm × 10 cm、相距 1.0 mm，$C = (8.854\\times10^{-12})(0.010)/0.0010 \\approx 89\\ \\text{pF}$；接 1000 V，板上電荷 $Q = CV \\approx 89\\ \\text{nC}$。可見 1 F 是非常大的電容，日常元件多是 pF 到 mF。</p>\n<p>其他形狀也能用同一套步驟算：假設帶 $\\pm Q$，用高斯定律求電場，積分得電位差，再算 $Q/V$。例如同軸圓柱 $C = 2\\pi\\varepsilon_0 L/\\ln(b/a)$，孤立導體球 $C = 4\\pi\\varepsilon_0 R$。</p>"
   },
   {
    "h": "儲存的能量與耐壓",
    "b": "<p>充電是一點一點把電荷 $dq$ 從負板搬到正板，每搬一次要克服當時的電位差 $v = q/C$。電位差越來越大，搬起來越來越費力，把功加總：</p>\n$$U = \\int_0^Q \\frac{q}{C}\\,dq = \\frac{Q^2}{2C} = \\frac{1}{2}QV = \\frac{1}{2}CV^2.$$\n<p>為什麼有個 ½？因為一開始電位差是零，最後才到 $V$，平均只有一半。</p>\n<p><b>耐壓</b>：每顆電容器都標了最大工作電壓，超過會讓中間的絕緣層崩潰。儲能和 $V^2$ 成正比，所以耐壓往往比電容值更重要。<b>小例題</b>（假設兩顆市售電容）：</p>\n<table><tr><th>電容器</th><th>最大電荷 $CV$</th><th>最大能量 $\\tfrac12CV^2$</th></tr>\n<tr><td>470 μF、耐壓 16 V</td><td>7.5 mC</td><td>0.060 J</td></tr>\n<tr><td>10 μF、耐壓 400 V</td><td>4.0 mC</td><td>0.80 J</td></tr></table>\n<p>電容小了 47 倍，能存的能量卻多了 13 倍。閃光燈與心臟去顫器用的都是高電壓電容器。</p>"
   },
   {
    "h": "並聯、串聯與介電質",
    "b": "<p><b>並聯與串聯</b></p>\n<table><tr><th></th><th>並聯</th><th>串聯</th></tr>\n<tr><td>什麼相同</td><td>每顆的電壓 $V$</td><td>每顆的電荷 $Q$</td></tr>\n<tr><td>什麼相加</td><td>電荷 $Q_1+Q_2$</td><td>電壓 $V_1+V_2$</td></tr>\n<tr><td>等效電容</td><td>$C = C_1 + C_2$</td><td>$\\dfrac{1}{C} = \\dfrac{1}{C_1}+\\dfrac{1}{C_2}$</td></tr>\n<tr><td>直覺</td><td>板面積變大</td><td>板間距變大</td></tr></table>\n<p><b>小例題</b>：2.0 μF 與 3.0 μF 並聯是 5.0 μF；串聯是 $(2.0)(3.0)/(2.0+3.0) = 1.2\\ \\mu\\text{F}$，比最小的那顆還小。串聯時電容小的那顆分到的電壓反而大（$V_i = Q/C_i$），所以要注意它的耐壓。</p>\n<p>遇到混合接法，就由內往外把「純並聯」或「純串聯」的一組換成一顆等效電容器，重畫電路，一步一步化簡。</p>\n<p><b>介電質</b>：在兩板之間塞進絕緣材料，材料裡的分子被電場極化：靠近正板的一側露出負電荷，靠近負板的一側露出正電荷。這層「束縛電荷」產生反向電場，把板間電場削弱成 $1/\\kappa$。同樣的 $Q$ 只需要較小的 $V$，所以</p>\n$$C = \\kappa C_0.$$\n<p>介電質有兩個好處：電容變成 $\\kappa$ 倍，而且它的崩潰電場通常比空氣（約 $3\\times10^{6}\\ \\text{V/m}$）高，板可以靠得更近、耐壓更高。常見的 $\\kappa$：空氣約 1.0006、紙約 3–4、水約 80，有些陶瓷材料可達數千，這也是小小的積層陶瓷電容能有很大電容值的原因。</p>\n<p><b>電池接著還是拔掉，結果不同</b>：接著電池時 $V$ 不變，塞進介電質後 $Q$ 變成 $\\kappa$ 倍；先拔掉電池再塞，$Q$ 不變，$V$ 降成 $1/\\kappa$，儲能 $Q^2/2C$ 也降成 $1/\\kappa$，少掉的能量變成把介電質「吸」進去的功。</p>"
   },
   {
    "h": "能量存在電場裡",
    "b": "<p>把平行板的儲能改寫：$\\tfrac12CV^2 = \\tfrac12(\\varepsilon_0A/d)(Ed)^2 = \\tfrac12\\varepsilon_0E^2\\cdot(Ad)$，而 $Ad$ 正是兩板之間有電場的體積。於是每單位體積的能量</p>\n$$u_E = \\frac{1}{2}\\varepsilon_0E^2.$$\n<p>這個式子對任何電場都成立，不限電容器。電場不均勻時，把每一小塊體積的 $u_E\\,dV$ 加起來就是總能量。<b>小例題</b>：10 cm × 10 cm、1.0 mm、1000 V 的平行板，$E = 1.0\\times10^{6}\\ \\text{V/m}$，$u_E \\approx 4.4\\ \\text{J/m}^3$，乘上 $1.0\\times10^{-5}\\ \\text{m}^3$ 得 44 μJ，和 $\\tfrac12CV^2$ 一致。</p>\n<p>能量密度能有多大？空氣在約 $3\\times10^{6}\\ \\text{V/m}$ 就會崩潰，此時 $u_E \\approx 40\\ \\text{J/m}^3$；汽油每立方公尺含化學能約 $3\\times10^{10}\\ \\text{J}$，大了將近十億倍。所以巨觀電場不適合大量儲能，但很適合「快速」放出能量。</p>\n<figure class=\"fig\"><img src=\"figs/fig_23_01_field_energy_sphere.svg\" alt=\"帶電導體球外的能量密度與累積能量比例\" loading=\"lazy\"><figcaption>能量密度隨 1/r⁴ 急速下降；把每一層球殼的能量加起來，球面到兩倍半徑之間就存了總能量的一半。</figcaption></figure>\n<p><b>拉開平行板要做功嗎？</b>先斷開電池（$Q$ 固定）再拉開，電場不變、有電場的體積變大，儲能跟著變大，多出來的能量來自拉開兩板的手；若電池一直接著（$V$ 固定），$C$ 變小、電荷流回電池，儲能反而變少。</p>\n<figure class=\"fig\"><img src=\"figs/fig_23_02_pulling_plates_apart.svg\" alt=\"拉開平行板時兩種條件下儲能的變化\" loading=\"lazy\"><figcaption>同一組平行板從 1 mm 拉到 5 mm：電荷固定時儲能變成 5 倍，電壓固定時剩 1/5。判斷之前先問電池有沒有接著。</figcaption></figure>"
   },
   {
    "h": "生活與科技連結",
    "b": "<ul>\n<li><b>心臟去顫器</b>：先把高壓電容器充電，再透過貼在胸口的電極在幾毫秒內放電，讓顫動的心肌同步重新開始收縮。原理和閃光燈一樣：慢慢存、快速放。</li>\n<li><b>手機觸控螢幕</b>：螢幕底下有透明導電的電極網格，手指靠近時改變電極之間的電容，控制晶片量到電容變化的位置，就知道你摸了哪裡。</li>\n<li><b>記憶體與超級電容</b>：電腦的動態隨機存取記憶體（DRAM）用極小的電容器有沒有帶電來存 0 與 1，電荷會慢慢漏掉，所以要定期重新寫入；超級電容則用極大的電極表面積做到數千法拉，用在需要瞬間大電流的場合。</li>\n</ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul>\n<li><b>以為電容由電壓或電荷決定</b>：$C = Q/V$ 只是定義與量法。電壓加倍，電荷也加倍，$C$ 不變；改變 $C$ 只能靠改變面積、距離或介電質。</li>\n<li><b>把串聯、並聯的公式和電阻搞混</b>：電容並聯直接相加、串聯取倒數和，剛好和電阻相反。可以用「並聯＝板面積變大、串聯＝板距變大」來記。</li>\n<li><b>沒先問電池接著沒</b>：塞介電質、拉開板子時，電池接著則 $V$ 固定，拔掉則 $Q$ 固定，儲能的變化方向可能完全相反。</li>\n</ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul>\n<li>23.1 節：一群點電荷的靜電能是每一對 $kq_iq_j/r_{ij}$ 的和，代表組合它們所需的功。</li>\n<li>23.2 節：電容的定義 $C = Q/V$，平行板電容 $\\varepsilon_0A/d$ 的推導，以及電容器儲能 $\\tfrac12CV^2$。</li>\n<li>23.3 節：實際使用電容器時的耐壓，並聯與串聯的等效電容，以及介電質如何讓電容變成 $\\kappa$ 倍。</li>\n<li>23.4 節：所有電場都存有能量，能量密度 $\\tfrac12\\varepsilon_0E^2$，以及用體積分算不均勻電場的總能量。</li>\n</ul>"
   }
