    "q": "兩個氫原子各自都是電中性，為什麼靠近之後會黏成一個氫分子，而兩個氦原子卻不會？",
    "a": "氫原子的 1s 只有一個電子，兩個原子靠近時，兩顆電子可以自旋相反、一起待在兩個原子核中間，同時被兩個核吸引，能量變低，於是形成共價鍵。氦的 1s 已經填滿兩顆電子，包立不相容原理不讓第三、第四顆擠進同一個低能態，靠近反而能量升高，所以不成鍵。"
