    "q": "微波爐用的電磁波頻率約 2.45 GHz，紅外線暖爐的頻率約 10¹³–10¹⁴ Hz。你猜分子吸收這兩種波時，分別在做什麼動作？",
    "a": "分子有三種「動法」：電子換軌道、原子間的鍵像彈簧一樣伸縮、整個分子轉圈。轉動的能階間隔最小，對應到微波；鍵的伸縮振動能階間隔較大，對應到紅外線；電子換軌道最大，對應可見光與紫外線。微波爐其實主要靠電場來回扭動液態水分子、經由碰撞生熱，和氣體分子的單一轉動能階躍遷不完全一樣。"
