    "q": "金屬加熱後電阻變大，矽晶片加熱後電阻反而變小。你覺得為什麼兩者剛好相反？",
    "a": "金屬本來就有大量可以自由移動的電子，溫度升高只是讓晶格振動得更厲害、電子更常被撞，所以電阻變大。矽的電子大多被綁在填滿的能帶裡，要跨過約 1.1 eV 的能隙才能導電；溫度升高讓更多電子跳上去，載子數目暴增，電阻因此變小。"
