    "a": "譜線變紅代表波長被拉長，可以理解為星系正在遠離我們（像都卜勒效應）。越遠的跑越快，表示整個宇宙在均勻膨脹：空間本身在伸展，任何兩個星系之間的距離都在變大。從哪個星系看出去都一樣，地球並不是中心。"
